// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetHealth Liveness and readiness
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// Login Log in with email and password (starts a new token family)
	// (POST /v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Revoke the refresh token family
	// (POST /v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// RefreshSession Rotate the refresh token
	// (POST /v1/auth/refresh)
	RefreshSession(w http.ResponseWriter, r *http.Request)
	// Register Start registration (emails a 6-digit verification code)
	// (POST /v1/auth/register)
	Register(w http.ResponseWriter, r *http.Request)
	// VerifyEmail Confirm the emailed code and set the password; creates the account, starts the trial, issues tokens
	// (POST /v1/auth/verify-email)
	VerifyEmail(w http.ResponseWriter, r *http.Request)
	// ResendVerification Email a new verification code for a pending sign-up
	// (POST /v1/auth/verify-email/resend)
	ResendVerification(w http.ResponseWriter, r *http.Request)
	// RegisterDevice Register or refresh a push token
	// (POST /v1/devices)
	RegisterDevice(w http.ResponseWriter, r *http.Request)
	// UnregisterDevice Remove a push token (logout / opt-out)
	// (DELETE /v1/devices/{deviceId})
	UnregisterDevice(w http.ResponseWriter, r *http.Request, deviceId Uuid)
	// ListEnabledFlags Modules enabled for the client (UX only; server enforces)
	// (GET /v1/flags)
	ListEnabledFlags(w http.ResponseWriter, r *http.Request)
	// ListLegalDocuments Current privacy notices and terms
	// (GET /v1/legal/documents)
	ListLegalDocuments(w http.ResponseWriter, r *http.Request)
	// DeleteMe Delete the account and all its data (irreversible; requires the current password)
	// (DELETE /v1/me)
	DeleteMe(w http.ResponseWriter, r *http.Request)
	// GetMe Current user profile
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Update profile (name only; email change is out of scope)
	// (PATCH /v1/me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// ListRegimes Regime catalog for one person type (support level, options, inputs, compatibility)
	// (GET /v1/regimes)
	ListRegimes(w http.ResponseWriter, r *http.Request, params ListRegimesParams)
	// GetReminderSettings Reminder preferences (defaults if never set)
	// (GET /v1/reminder-settings)
	GetReminderSettings(w http.ResponseWriter, r *http.Request)
	// PutReminderSettings Replace reminder preferences
	// (PUT /v1/reminder-settings)
	PutReminderSettings(w http.ResponseWriter, r *http.Request)
	// GetSubscription Access status (trial, pro, comp, read-only) and plan
	// (GET /v1/subscription)
	GetSubscription(w http.ResponseWriter, r *http.Request)
	// SyncSubscription Pull current state from RevenueCat (post-purchase / restore)
	// (POST /v1/subscription/sync)
	SyncSubscription(w http.ResponseWriter, r *http.Request)
	// GetTaxCalendar Monthly due dates for a year (day 17 moved past weekends/holidays)
	// (GET /v1/tax-calendar)
	GetTaxCalendar(w http.ResponseWriter, r *http.Request, params GetTaxCalendarParams)
	// ListTaxpayers Taxpayers managed by the user (feeds the active-taxpayer switcher)
	// (GET /v1/taxpayers)
	ListTaxpayers(w http.ResponseWriter, r *http.Request, params ListTaxpayersParams)
	// CreateTaxpayer Create a taxpayer with its regimes and options in one transaction (onboarding)
	// (POST /v1/taxpayers)
	CreateTaxpayer(w http.ResponseWriter, r *http.Request)
	// DeleteTaxpayer Permanently delete a taxpayer and all its records (irreversible)
	// (DELETE /v1/taxpayers/{taxpayerId})
	DeleteTaxpayer(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, params DeleteTaxpayerParams)
	// GetTaxpayer Get a taxpayer (archived ones too)
	// (GET /v1/taxpayers/{taxpayerId})
	GetTaxpayer(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId)
	// UpdateTaxpayer Rename a taxpayer or correct its RFC (person type is immutable)
	// (PATCH /v1/taxpayers/{taxpayerId})
	UpdateTaxpayer(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId)
	// ArchiveTaxpayer Archive (hide) a taxpayer, keeping its data
	// (POST /v1/taxpayers/{taxpayerId}/archive)
	ArchiveTaxpayer(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId)
	// GetDashboard Home for the active taxpayer
	// (GET /v1/taxpayers/{taxpayerId}/dashboard)
	GetDashboard(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, params GetDashboardParams)
	// GetTaxpayerEstimate Monthly IVA + provisional ISR estimate of one month, per regime and total
	// (GET /v1/taxpayers/{taxpayerId}/estimates)
	GetTaxpayerEstimate(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, params GetTaxpayerEstimateParams)
	// GetEstimateBreakdown Step-by-step computation of one regime's estimate, with legal basis
	// (GET /v1/taxpayers/{taxpayerId}/estimates/{period}/breakdown)
	GetEstimateBreakdown(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, period PeriodPath, params GetEstimateBreakdownParams)
	// ListExpenseCategories Expense categories with deductibility resolved for the taxpayer's regime and options
	// (GET /v1/taxpayers/{taxpayerId}/expense-categories)
	ListExpenseCategories(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, params ListExpenseCategoriesParams)
	// ListExpenses List a month's expenses (keyset pagination) with period totals
	// (GET /v1/taxpayers/{taxpayerId}/expenses)
	ListExpenses(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, params ListExpensesParams)
	// CreateExpense Record an expense (idempotent client id; trial cap enforced)
	// (POST /v1/taxpayers/{taxpayerId}/expenses)
	CreateExpense(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId)
	// DeleteExpense Soft-delete an expense (Undo via restore)
	// (DELETE /v1/taxpayers/{taxpayerId}/expenses/{expenseId})
	DeleteExpense(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, expenseId ExpenseId)
	// GetExpense Get an expense
	// (GET /v1/taxpayers/{taxpayerId}/expenses/{expenseId})
	GetExpense(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, expenseId ExpenseId)
	// UpdateExpense Edit an expense (merge-patch; null clears a nullable field or the override)
	// (PATCH /v1/taxpayers/{taxpayerId}/expenses/{expenseId})
	UpdateExpense(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, expenseId ExpenseId)
	// RestoreExpense Undo a delete (never consumes a trial slot)
	// (POST /v1/taxpayers/{taxpayerId}/expenses/{expenseId}/restore)
	RestoreExpense(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, expenseId ExpenseId)
	// GetHistory Monthly summaries for a fiscal year
	// (GET /v1/taxpayers/{taxpayerId}/history)
	GetHistory(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, params GetHistoryParams)
	// MarkHistoryViewed Mark a month as viewed (stores the current records fingerprint)
	// (POST /v1/taxpayers/{taxpayerId}/history/{period}/viewed)
	MarkHistoryViewed(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, period PeriodPath)
	// ListIncomes List a month's incomes (keyset pagination) with period totals
	// (GET /v1/taxpayers/{taxpayerId}/incomes)
	ListIncomes(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, params ListIncomesParams)
	// CreateIncome Record an income (idempotent client id; trial cap enforced)
	// (POST /v1/taxpayers/{taxpayerId}/incomes)
	CreateIncome(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId)
	// GetIncomeDefaults IVA rates and suggested withholding rates for a new income (prefills the form)
	// (GET /v1/taxpayers/{taxpayerId}/incomes/defaults)
	GetIncomeDefaults(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, params GetIncomeDefaultsParams)
	// DeleteIncome Soft-delete an income (Undo via restore)
	// (DELETE /v1/taxpayers/{taxpayerId}/incomes/{incomeId})
	DeleteIncome(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, incomeId IncomeId)
	// GetIncome Get an income
	// (GET /v1/taxpayers/{taxpayerId}/incomes/{incomeId})
	GetIncome(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, incomeId IncomeId)
	// UpdateIncome Edit an income (merge-patch; null clears a nullable field)
	// (PATCH /v1/taxpayers/{taxpayerId}/incomes/{incomeId})
	UpdateIncome(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, incomeId IncomeId)
	// RestoreIncome Undo a delete (never consumes a trial slot)
	// (POST /v1/taxpayers/{taxpayerId}/incomes/{incomeId}/restore)
	RestoreIncome(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, incomeId IncomeId)
	// AddTaxpayerRegime Add a regime to a taxpayer (or reopen an ended one)
	// (POST /v1/taxpayers/{taxpayerId}/regimes)
	AddTaxpayerRegime(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId)
	// ArchiveTaxpayerRegime End a regime at `end_period` (records are kept; never a hard delete)
	// (DELETE /v1/taxpayers/{taxpayerId}/regimes/{regimeCode})
	ArchiveTaxpayerRegime(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, regimeCode RegimeCodePath, params ArchiveTaxpayerRegimeParams)
	// UpdateTaxpayerRegime Change a regime's options (applies to every period of the regime)
	// (PATCH /v1/taxpayers/{taxpayerId}/regimes/{regimeCode})
	UpdateTaxpayerRegime(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, regimeCode RegimeCodePath)
	// GetTaxInputs Tax inputs of one regime and fiscal year, with their definitions
	// (GET /v1/taxpayers/{taxpayerId}/regimes/{regimeCode}/tax-inputs)
	GetTaxInputs(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, regimeCode RegimeCodePath, params GetTaxInputsParams)
	// PutTaxInputs Replace the tax inputs of one regime and fiscal year
	// (PUT /v1/taxpayers/{taxpayerId}/regimes/{regimeCode}/tax-inputs)
	PutTaxInputs(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId, regimeCode RegimeCodePath, params PutTaxInputsParams)
	// UnarchiveTaxpayer Unarchive a taxpayer (it returns to the list and the switcher)
	// (POST /v1/taxpayers/{taxpayerId}/unarchive)
	UnarchiveTaxpayer(w http.ResponseWriter, r *http.Request, taxpayerId TaxpayerId)
	// ReceiveRevenueCatWebhook RevenueCat webhook receiver (idempotent by event id)
	// (POST /v1/webhooks/revenuecat)
	ReceiveRevenueCatWebhook(w http.ResponseWriter, r *http.Request)
}

